// Deterministic cross-layer corpus: boundary cases plus a Cartesian grammar mutation sample.
const boundary = [
  'person@example.invalid',
  'PERSON@EXAMPLE.INVALID',
  ' person@example.invalid ',
  'a.b+c@example.invalid',
  'a..b@example.invalid',
  '.a@example.invalid',
  'a.@example.invalid',
  'a@localhost',
  'a@-example.invalid',
  'a@example-.invalid',
  'a@example..invalid',
  'a@ex_ample.invalid',
  'a@éxample.invalid',
  'ü@example.invalid',
  'a\r\nbcc:x@example.invalid',
  'a\0@example.invalid',
  'a\t@example.invalid',
  'a\u007f@example.invalid',
  `${'a'.repeat(64)}@example.invalid`,
  `${'a'.repeat(65)}@example.invalid`,
  `a@${'b'.repeat(63)}.invalid`,
  `a@${'b'.repeat(64)}.invalid`,
  `${'a'.repeat(64)}@${'b'.repeat(63)}.${'c'.repeat(63)}.${'d'.repeat(61)}`,
  `${'a'.repeat(64)}@${'b'.repeat(63)}.${'c'.repeat(63)}.${'d'.repeat(62)}`,
  'a@example.invalid\n',
  'a@example.invalid\r',
  '',
  'a@@example.invalid',
];
export const emailCorpus: readonly string[] = Object.freeze([
  ...new Set([
    ...boundary,
    ...['a', 'a.b', 'a..b', 'a-', 'a+tag', "a'b", 'A', 'a b', 'ю', 'a\n'].flatMap((local) =>
      [
        'example.invalid',
        'x.y',
        'a-b.invalid',
        '-a.invalid',
        'a-.invalid',
        'a..invalid',
        'а.invalid',
        'localhost',
        'a_b.invalid',
        'example.invalid.',
      ].map((domain) => `${local}@${domain}`),
    ),
  ]),
]);
